#!/bin/bash
P="$(cd "$(dirname "$0")/.." && pwd)"; cd $P/assets/raw
[ -s npcs.png ] || codex exec --skip-git-repo-check -s workspace-write -C $P/assets/raw "Use your image generation tool to create ONE NEW image (never reuse an existing file) and save it as $P/assets/raw/npcs.png. 1536x1024 SPRITE SHEET, TRANSPARENT background, same chibi HD pixel-art style and proportions as the attached hero reference sheet. Follow the attached template: 4 rows x 4 columns of 384x256 cells. Each row = ONE villager doing a 4-frame walk cycle facing RIGHT (contact, down, passing, up), same size in every cell, feet on the red baseline. Row 1 merchant with apron and a sack; row 2 farmer with straw hat and a hoe; row 3 small child with a wooden toy sword; row 4 town guard with a spear and blue tabard. Villagers are about 85% the height of the heroes (child 60%). No grid lines, no text." -i npc-template.png -i hero-warrior.png < /dev/null > npcs.png.log 2>&1
echo "npcs.png rc=$?" >> gen.log; echo NPCDONE >> gen.log
